let state=structuredClone(seed);try{const saved=JSON.parse(localStorage.getItem('auriga-admin-design-v1'));if(saved?.version===1&&saved.data?.resources&&saved.data?.audit)state=saved.data}catch{}
let role='super',page='overview',tab='',query='',filter='all',resourceTab='content',focusBefore,toastTimer;
const roleNames={super:'超级管理员',admin:'管理员',reviewer:'资源审核员'};
const permitted=p=>role==='super'||(role==='admin'?['overview','resources','members','runtime','ops','audit'].includes(p):['overview','resources','audit'].includes(p));
const persist=()=>{try{localStorage.setItem('auriga-admin-design-v1',JSON.stringify({version:1,data:state}));return true}catch{return false}};
function toast(message){$('toast').textContent=message;$('toast').className='show';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').className='',3200)}
function record(event,target,category){state.audit.unshift({id:'evt-'+Date.now(),at:new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date()),actor:'林清',event,target,result:'模拟成功',category});if(!persist())toast('浏览器存储不可用，本次修改仅在当前页面有效。')}
const pending=()=>state.resources.filter(r=>r.status==='pending');
const visibleAudit=()=>state.audit.filter(a=>role==='super'||(role==='reviewer'?a.category==='资源':a.id!=='evt-04'));
const availableTabs=p=>p==='resources'&&role==='reviewer'?tabs.resources.filter(t=>t[0]==='review'):tabs[p]||[];
function navigate(p,t=''){if(!permitted(p))p='overview';const hash='#/'+p+(t?'/'+t:'');if(location.hash===hash)readRoute();else location.hash=hash}
function readRoute(){let [p,t]=location.hash.replace(/^#\/?/,'').split('/');page=nav.some(n=>n[0]===p)&&permitted(p)?p:'overview';tab=availableTabs(page).some(x=>x[0]===t)?t:availableTabs(page)[0]?.[0]||'';query='';filter='all';close();render();$('main').scrollTop=0}
function render(keepSearch=false){$('navigation').innerHTML=nav.filter(([id])=>permitted(id)).map(([id,label,group])=>(group?'<div class="nav-group">'+group+'</div>':'')+'<a class="navlink" href="#/'+id+'" '+(page===id?'aria-current="page"':'')+'>'+icon(id)+'<span>'+label+'</span>'+(id==='resources'&&pending().length?'<small class="count">'+pending().length+'</small>':'')+'</a>').join('');$('crumb').textContent=nav.find(n=>n[0]===page)[1];$('role-label').textContent=roleNames[role];document.querySelector('[data-action="theme"]').innerHTML=icon('theme');const title=nav.find(n=>n[0]===page)[1];$('main').innerHTML='<div class="page-head"><div><h1>'+title+'</h1>'+(page==='overview'?'<div class="meta">2026 年 10 月 23 日 · 运行与待办</div>':'')+'</div><div class="head-actions">'+(page==='members'&&tab==='invites'&&role!=='reviewer'?btn('＋ 创建邀请','invite','','primary'):'')+btn(icon('overview')+' 更新视图','refresh')+'</div></div>'+(page==='overview'?overview():'<div class="tabs" role="tablist" aria-label="'+title+'分类">'+availableTabs(page).map(([id,label])=>'<button class="tab" role="tab" aria-selected="'+(tab===id)+'" data-action="tab" data-id="'+id+'">'+label+'</button>').join('')+'</div>'+pageContent())+'<div class="footnote">交互设计原型 · 所有数据及操作均为模拟</div>';if(keepSearch){const el=$('search');el?.focus();el?.setSelectionRange(query.length,query.length)}}
function overview(){const running=state.instances.filter(x=>x.status==='running').length;return headquartersEntry()+'<div class="stats">'+[['待审核资源',pending().length,'待发布 '+state.resources.filter(x=>x.status==='approved').length+' 个版本','resources','review'],['运行中实例',running,'共 '+state.instances.length+' 个云端实例','runtime','instances'],['在线终端',state.devices.filter(x=>x.status==='online').length,'共 '+state.devices.length+' 个现场终端','runtime','devices'],['待处理异常',2,'节点离线 · 模型服务异常','ops','alerts']].map(([label,value,foot,p,t])=>'<button class="stat" data-action="go" data-id="'+p+'/'+t+'" '+(!permitted(p)?'disabled':'')+'><span class="stat-label">'+label+icon(p)+'</span><div class="stat-number">'+value+'</div><div class="stat-foot">'+foot+'</div></button>').join('')+'</div><div class="overview-grid"><div class="stack"><section class="panel"><div class="panel-head"><h2>需要处理</h2><span>按优先级</span></div>'+[['alert','节点离线','node-linux-02 · 1 个实例受影响','runtime/nodes','查看节点'],['models','模型服务连续失败','备用模型 · 最近探测超时','models/providers','查看服务'],['resources','资源等待审核',pending().length+' 个新版本待处理','resources/review','去审核']].filter(x=>permitted(x[3].split('/')[0])).map(([i,title,desc,target,act])=>'<div class="task-row"><div class="task-symbol">'+icon(i)+'</div><div class="task-body"><div class="task-title">'+title+'</div><span class="sub">'+desc+'</span></div><button class="text-btn" data-action="go" data-id="'+target+'">'+act+' →</button></div>').join('')+'</section><section class="panel"><div class="panel-head"><h2>最新提交</h2><button class="text-btn" data-action="go" data-id="resources/review">全部审核 →</button></div>'+table(['资源','提交人','版本',''],pending().slice(0,3).map(r=>['<button class="name-button" data-action="resource" data-id="'+r.id+'">'+r.name+'</button><span class="sub">'+r.kind+'</span>',r.author,'<span class="mono">'+r.version+'</span>',btn('查看','resource',r.id,'small')]))+'</section></div><div class="stack"><section class="panel"><div class="panel-head"><h2>运行状态</h2><span>示例快照</span></div>'+[['控制面','ok'],['运行节点 · 2 / 3 在线','warning'],['资源签发','ok'],['最近备份 · 今日 02:00','ok']].map(([name,s])=>'<div class="health-row"><span>'+name+'</span>'+badge(s)+'</div>').join('')+'</section><section class="panel"><div class="panel-head"><h2>最近操作</h2><button class="text-btn" data-action="go" data-id="audit">查看审计 →</button></div>'+visibleAudit().slice(0,4).map(a=>'<div class="task-row"><div class="task-body"><div class="task-title">'+esc(a.event)+'</div><span class="sub">'+esc(a.actor+' · '+a.target)+'</span></div><span class="mono">'+esc(a.at.split(' ').at(-1))+'</span></div>').join('')+'</section></div></div>'}
function table(headers,rows){return '<div class="table-wrap"><table><thead><tr>'+headers.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.map(cols=>'<tr>'+cols.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
function filtered(rows){return rows.filter(r=>(filter==='all'||r.status===filter)&&(r.search||r.cells.map(c=>String(c).replace(/<[^>]*>/g,'')).join(' ')).toLowerCase().includes(query.toLowerCase()))}
function listing(headers,rows,placeholder='搜索名称、负责人…'){const shown=filtered(rows),states=[...new Set(rows.map(r=>r.status).filter(Boolean))];return '<div class="toolbar"><div class="filters">'+(states.length?'<select id="status-filter" aria-label="状态筛选"><option value="all">全部状态</option>'+states.map(s=>'<option value="'+esc(s)+'" '+(s===filter?'selected':'')+'>'+esc(labels[s]||s)+'</option>').join('')+'</select>':'')+'<span class="sub">'+shown.length+' 项</span></div><label class="search">'+icon('search')+'<input id="search" aria-label="搜索当前列表" value="'+esc(query)+'" placeholder="'+placeholder+'"></label></div><section class="panel">'+(shown.length?table(headers,shown.map(r=>r.cells)):'<div class="empty"><strong>没有符合条件的记录</strong><span>调整搜索关键词或筛选条件。</span><br>'+btn('清除筛选','clear')+'</div>')+'<div class="table-footer"><span>共 '+shown.length+' 项</span><span>第 1 页</span></div></section>'}
function pageContent(){if(page==='resources')return resourcesPage();if(page==='members')return membersPage();if(page==='runtime')return runtimePage();if(page==='models')return modelsPage();if(page==='security')return securityPage();if(page==='ops')return opsPage();return listing(['时间','操作人','操作','对象','结果'],visibleAudit().map(a=>({status:a.category,cells:[esc(a.at),esc(a.actor),'<button class="name-button" data-action="audit" data-id="'+a.id+'">'+esc(a.event)+'</button>',esc(a.target),badge(a.result)]})),'搜索操作人、事件、对象…')}
function resourcesPage(){if(tab==='distribution')return '<div class="notice subtle">等级决定安装与管理方式；资源审核和发布单独进行。</div>'+cards([
['L0 · 核心插件','随部署升级，管理台只读。','Auriga 认证与接入','core'],['L1 · 系统插件','管理员统一维护，成员不能关闭或卸载。','统一分发','l1'],['L2 · 默认插件','默认安装，成员可以关闭但不能卸载。','按策略生效','l2'],['L3 · 可选插件','审核发布后，成员自行安装与卸载。','资源市场','l3'],['L4 · 私有插件','仅本人可见，受个人上传策略约束。','未审核 · 不自动公开','l4'],['分发状态','区分已下发、应用中、已生效与失败。','以节点回报为准','distribution']]);const review=tab==='review',rows=state.resources.filter(r=>review?['pending','approved','rejected'].includes(r.status):['published','withdrawn'].includes(r.status));return (review?'<div class="notice subtle">审核通过后进入待发布；发布完成才会出现在资源市场。</div>':'')+listing(['资源 / 版本','类型','作者','范围','状态','提交时间',''],rows.map(r=>({status:r.status,search:r.name+' '+r.author+' '+r.kind+' '+r.version,cells:['<button class="name-button" data-action="resource" data-id="'+r.id+'">'+esc(r.name)+'</button><span class="sub mono">v'+r.version+'</span>',r.kind+(r.proposal?'<span class="tag">提案</span>':''),r.author,r.scope,badge(r.status),'<span class="mono">'+r.date+'</span>',btn(r.status==='approved'?'查看并发布':'查看','resource',r.id,'small')]})))}
function membersPage(){if(tab==='users')return listing(['成员','角色','分组','身份源','状态','最近访问',''],state.members.map(u=>({status:u.status,cells:['<button class="name-button" data-action="member" data-id="'+u.id+'">'+u.name+'</button><span class="sub mono">'+u.id+'</span>',u.role,u.group,u.source,badge(u.status),u.last,btn('详情','member',u.id,'small')]})));if(tab==='invites')return listing(['邀请','默认角色','分组','已用 / 名额','有效期','状态'],state.invites.map(i=>({status:i.status,cells:[esc(i.name),esc(i.role),esc(i.group),esc(i.usage),esc(i.expiry),badge(i.status)]})));if(tab==='groups')return cards(['平台维护','研发','设计'].map(g=>[g,'按成员分组组织授权与配额，不作为独立团队切换。',state.members.filter(u=>u.group===g).length+' 名成员','group-'+g]));return cards([['超级管理员','身份源、全局策略、角色管理与平台运维。','平台配置权限','role-super'],['管理员','成员维护、实例运维、资源治理与授权审计。','日常管理权限','role-admin'],['资源审核员','查看送审内容并作出审核决定。','最小审核权限 · 提案','role-reviewer'],['成员','使用个人 DSH 与获授权的公开资源。','不进入管理台','role-member']])}
function runtimePage(){if(tab==='headquarters')return headquartersPage();if(tab==='instances')return listing(['实例','所属成员','节点','状态','CPU / 内存','活动',''],state.instances.map(i=>({status:i.status,cells:['<button class="name-button" data-action="instance" data-id="'+i.id+'">'+i.name+'</button><span class="sub mono">'+i.id+'</span>',i.owner,'<span class="mono">'+i.node+'</span>',badge(i.status),(i.cpu===null?'未知':i.cpu+'%')+'<span class="sub">'+i.memory+'</span>',i.activity,btn('详情','instance',i.id,'small')]})));if(tab==='devices')return '<div class="notice subtle">现场终端单独管理接入状态，不作为总部托管的云端实例启停。</div>'+listing(['终端','所属成员','系统','插件版本','连接','最近心跳',''],state.devices.map(d=>({status:d.status,cells:[d.name,d.owner,d.os,d.version,badge(d.status),d.heartbeat,btn('详情','device',d.id,'small')]})));return listing(['节点','运行驱动','状态','运行实例','内存用量','最近心跳',''],state.nodes.map(n=>({status:n.status,cells:['<span class="mono">'+n.name+'</span>',n.driver,badge(n.status),n.capacity,n.memory,n.heartbeat,btn('详情','node',n.id,'small')]})))}
const providers=[{id:'model-1',name:'通用模型',provider:'供应商 A',status:'ok',scope:'研发、设计',requests:'1,284',p95:'1.8 秒'},{id:'model-2',name:'推理模型',provider:'供应商 B',status:'ok',scope:'研发',requests:'416',p95:'4.2 秒'},{id:'model-3',name:'备用模型',provider:'供应商 C',status:'error',scope:'平台维护',requests:'23',p95:'探测超时'}];
function modelsPage(){return modelWorkspace()}
function securityPage(){if(tab==='identity')return cards([['内置账号','邀请注册、口令、多因素与 Passkey。','已启用','id-native'],['标准 OIDC','通过统一身份源接入用户登录。','已启用 · 配置示例','id-oidc'],['应急账号','平台恢复入口，强制多因素验证。','系统保留','id-emergency']]);if(tab==='entries')return '<div class="notice subtle">入口由部署配置管理，此处只读。业务源与管理源使用独立会话。</div>'+listing(['入口','示例地址','用途','状态'],[['业务入口','https://work.auriga.example','用户登录、云端 DSH、资源接口'],['管理入口','https://admin.auriga.example','管理台与管理接口']].map(a=>({status:'ok',cells:[a[0],'<span class="mono">'+a[1]+'</span>',a[2],badge('ok')]})));return cards([['默认出网规则','云端实例经受控出口访问获准服务。','白名单模式','egress-default'],['模型服务','仅允许配置的上游模型服务地址。','3 个示例服务','egress-models'],['策略覆盖','展示策略继承及例外的有效范围。','按分组授权','egress-groups']])}
function opsPage(){if(tab==='alerts')return listing(['级别','事件','影响对象','首次发现','状态',''],[{status:'warning',cells:[badge('warning'),'节点心跳超时','node-linux-02 · 1 个实例','10-23 16:30','待处理',btn('查看节点','go','runtime/nodes','small')]},{status:'error',cells:[badge('error'),'模型服务探测超时','备用模型','10-23 15:48','待处理',permitted('models')?btn('查看模型','go','models/providers','small'):'联系平台配置管理员']}]);if(tab==='backups')return '<div class="notice subtle">备份成功与恢复验证分别记录，未验证的备份不标为可恢复。</div>'+listing(['备份任务','范围','完成时间','备份结果','恢复验证',''],[['backup-1023','平台数据与配置','10-23 02:00','成功','待验证'],['backup-1022','平台数据与配置','10-22 02:00','成功','已验证']].map(a=>({status:a[4],cells:[...a,btn('详情','backup',a[0],'small')]})));if(tab==='lifecycle')return listing(['成员','账号','实例','数据处置','状态',''],[{status:'待交接',cells:['沈嘉',badge('disabled'),'已停止','保留数据，待指定接手人','待交接',btn('查看流程','lifecycle','u6','small')]}]);return cards([['实例默认配额','CPU、内存、存储与并发上限。','2 核 / 2 GB / 20 GB','quota'],['闲置回收','停止空闲实例并保留数据；常驻需明确原因。','空闲 30 分钟 · 示例','idle'],['运行时版本','管理 DSH、节点代理与核心插件的部署版本。','由部署流程更新','runtime-version'],['数据留存','审计留存与导出、备份保留策略。','90 天 · 示例','retention'],['通知渠道','平台异常与管理事件的通知配置。','站内通知','notifications'],['部署与许可证','查看部署形态、版本与许可状态。','自托管部署','deployment']])}
function cards(items){return '<div class="catalog-cards">'+items.map(([title,desc,value,id])=>'<section class="policy-card"><h3>'+esc(title)+'</h3><p>'+esc(desc)+'</p><div class="value">'+esc(value)+'</div>'+btn('查看详情','policy',id)+'<template id="policy-'+esc(id)+'">'+esc(JSON.stringify({title,desc,value}))+'</template></section>').join('')+'</div>'}
function close(){const had=$('overlay').children.length;$('shell').inert=false;$('overlay').innerHTML='';if(had&&focusBefore?.isConnected)focusBefore.focus();focusBefore=null}
function openDialog(title,body,footer='',modal=false){if(!$('overlay').children.length)focusBefore=document.activeElement;$('shell').inert=true;$('overlay').innerHTML=modal?'<div class="overlay modal-wrap"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">'+esc(title)+'</h2>'+body+'<div class="modal-actions">'+footer+'</div></section></div>':'<div class="overlay"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="drawer-head"><div><div class="eyebrow">AURIGA / 管理详情</div><h2 id="dialog-title">'+esc(title)+'</h2></div><button class="icon-btn" data-action="close" aria-label="关闭详情">'+icon('close')+'</button></header><div class="drawer-body">'+body+'</div>'+(footer?'<footer class="drawer-footer">'+footer+'</footer>':'')+'</section></div>';$('overlay').querySelector('button:not(:disabled),input,select,textarea')?.focus()}
const facts=items=>'<dl class="facts">'+items.map(([k,v])=>'<div><dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl>';
function resourceDetail(id,t='content'){const r=state.resources.find(r=>r.id===id);if(!r)return;resourceTab=t;let content=t==='content'?'<h3 class="detail-h">本次变更</h3><p>'+esc(r.change)+'</p><h3 class="detail-h">版本内容</h3><pre class="code">'+esc(r.content)+'</pre><h3 class="detail-h">文件清单</h3><pre class="code">'+esc(r.files)+'</pre>':t==='permissions'?'<h3 class="detail-h">声明的访问范围</h3><pre class="code">'+esc(r.permissions)+'</pre><div class="notice subtle">权限声明与包核验分别检查；声明不代表已获得访问授权。</div>':'<div class="change-line"><b>'+r.date+'</b> '+r.author+' 提交 v'+r.version+'</div>'+state.audit.filter(a=>a.target===r.name+' · '+r.version).reverse().map(a=>'<div class="change-line"><b>'+esc(a.at)+'</b> '+esc(a.actor+' · '+a.event)+'</div>').join('');if(t==='history'&&r.reason)content+='<h3 class="detail-h">审核意见</h3><pre class="code">'+esc(r.reason)+'</pre>';const authorSelf=r.author==='林清',canPublish=role!=='reviewer'&&!authorSelf;let foot='';if(r.status==='pending'){content+=(authorSelf?'<div class="notice">这是你提交的版本，请由其他审核者处理。</div>':'<label class="reason">审核意见<textarea id="review-reason" placeholder="驳回时必填；通过时可补充说明"></textarea></label><div class="error" id="review-error" role="alert"></div>');foot=authorSelf?'<span class="sub">作者不能审核或发布自己的共享版本</span>':btn('驳回','reject',id,'danger')+btn('通过审核','approve',id,'primary')}if(r.status==='approved'){content+='<div class="notice">审核已通过。发布将绑定当前版本与摘要，完成签发后上架。</div>';foot=canPublish?btn('发布版本','publish-confirm',id,'primary'):'<span class="sub">'+(authorSelf?'作者不能发布自己的共享版本':'等待具有发布权限的管理员处理')+'</span>'}if(r.status==='published'&&role!=='reviewer')foot=btn('普通下架','withdraw-confirm',id,'danger');openDialog(r.name, facts([['类型',r.kind+(r.proposal?' · 设计提案':'')],['状态',labels[r.status]],['作者',r.author],['版本',r.previous+' → '+r.version],['可见范围',r.scope],['分发等级',r.tier]])+(r.proposal?'<div class="notice subtle">此类型为产品设计提案；当前正式资源安装契约首批仅覆盖插件。</div>':'')+'<div class="tabs" role="tablist" aria-label="资源详情分类">'+[['content','版本内容'],['permissions','权限声明'],['history','审核记录']].map(([key,label])=>'<button class="tab" role="tab" aria-selected="'+(t===key)+'" data-action="resource-tab" data-id="'+id+':'+key+'">'+label+'</button>').join('')+'</div>'+content,foot)}
function decision(id,approve){const r=state.resources.find(r=>r.id===id);if(!r||r.status!=='pending'||r.author==='林清')return;const reason=$('review-reason')?.value.trim()||'';if(!approve&&!reason){$('review-error').textContent='请填写驳回原因。';$('review-reason').focus();return}r.status=approve?'approved':'rejected';r.reason=reason;record(approve?'通过资源审核':'驳回资源版本',r.name+' · '+r.version,'资源');render();resourceDetail(id,'history');toast(approve?'已模拟通过审核，版本进入待发布。':'已模拟驳回，审核意见已记录。')}
function instanceDetail(id){const i=state.instances.find(i=>i.id===id);if(!i)return;const transit=['starting','stopping'].includes(i.status);openDialog(i.name,facts([['所属成员',i.owner],['节点',i.node],['实际状态',labels[i.status]],['当前规格',i.quota],['期望版本',String(i.generation)],['已观察版本',String(i.observed)]])+'<div class="notice subtle">只展示运行元数据，不进入成员的会话、文件或个人记忆。</div><h3 class="detail-h">运行状态</h3><div class="change-line">'+esc(i.activity)+'</div>'+(transit?'<div class="notice">操作已登记，等待节点回报。尚未标记为执行完成。</div>':''),(transit?btn('模拟节点回报','instance-observed',id):i.status==='running'?btn('停止实例','instance-stop',id,'danger'):i.status==='stopped'?btn('启动实例','instance-start',id,'primary'):btn('查看节点','go','runtime/nodes')))}
function details(type,id){if(type==='member'){const u=state.members.find(u=>u.id===id);openDialog(u.name,facts([['账号',u.id],['角色',u.role],['分组',u.group],['身份源',u.source],['状态',labels[u.status]],['最近访问',u.last]])+'<div class="notice subtle">成员管理不包含读取其个人会话、文件、记忆或模型密钥。</div><h3 class="detail-h">资源与运行</h3><div class="change-line">云端实例 '+state.instances.filter(i=>i.owner===u.name).length+' 个</div><div class="change-line">现场终端 '+state.devices.filter(i=>i.owner===u.name).length+' 个</div>',btn('查看云端实例','go','runtime/instances'));return}if(type==='device'){const d=state.devices.find(x=>x.id===id);openDialog(d.name,facts([['所属成员',d.owner],['系统',d.os],['接入状态',labels[d.status]],['插件版本',d.version],['最近心跳',d.heartbeat],['设备编号',d.id]])+'<div class="notice subtle">现场终端的本地资源留在现场；总部管理连接身份、接入授权和资源分发。</div>');return}if(type==='node'){const n=state.nodes.find(x=>x.id===id);openDialog(n.name,facts([['运行驱动',n.driver],['节点状态',labels[n.status]],['运行实例',n.capacity],['内存',n.memory],['最近心跳',n.heartbeat]])+'<h3 class="detail-h">关联实例</h3>'+state.instances.filter(i=>i.node===n.name).map(i=>'<div class="health-row"><span>'+i.name+'</span>'+badge(i.status)+'</div>').join('')+(n.status==='offline'?'<div class="notice">节点离线期间指标显示未知；不可把旧心跳当作当前健康状态。</div>':''));return}if(type==='model'){const m=providers.find(x=>x.id===id);openDialog(m.name,facts([['供应商',m.provider],['健康状态',labels[m.status]],['授权范围',m.scope],['凭据', '服务端托管 · 不回显'],['今日请求',m.requests],['P95 首字延迟',m.p95]])+'<h3 class="detail-h">服务策略</h3><div class="change-line">请求超时与重试由网关统一控制</div><div class="change-line">预算计量仅覆盖经过平台的调用</div><div class="notice subtle">供应商地址、模型参数、授权和预算在同一详情中配置。当前为只读设计示例。</div>');return}if(type==='audit'){const a=state.audit.find(x=>x.id===id);openDialog('审计详情',facts([['事件编号',a.id],['时间',a.at],['操作人',a.actor],['操作',a.event],['对象',a.target],['结果',a.result]])+'<div class="notice subtle">正式审计由服务端记录，包含请求关联标识与变更结果；此处为浏览器内的演示记录。</div>');return}if(type==='policy'){const data=JSON.parse($('policy-'+id).content.textContent);openDialog(data.title,facts([['当前策略',data.value],['管理范围',roleNames[role]]])+'<p>'+esc(data.desc)+'</p><div class="notice subtle">策略详情示意。正式变更需展示影响范围、配置来源、权限与执行结果。</div>'+((id==='l0'||id==='core')?'<div class="change-line">核心认证插件版本由部署流程管理，不能在市场中替换。</div>':''));return}if(type==='backup'){openDialog('备份详情',facts([['任务编号',id],['范围','平台数据与配置'],['备份结果','成功 · 示例'],['恢复验证',id==='backup-1023'?'待验证':'已验证 · 示例']])+'<div class="notice subtle">恢复需明确目标和影响范围，再次确认身份；原型不执行恢复。</div>');return}if(type==='lifecycle')openDialog('成员离职处置',facts([['成员','沈嘉'],['账号','已停用'],['数据','保留中'],['接手人','待指定']])+'<div class="change-line">1. 停用身份与接入凭据</div><div class="change-line">2. 停止实例并保留数据</div><div class="change-line">3. 指定资源交接人，处理已发布内容</div><div class="change-line">4. 经授权导出或到期清理，保留审计</div><div class="notice subtle">当前仅展示处置流程，不提供一键删除个人数据。</div>')}
function confirmAction(action,id){const r=state.resources.find(x=>x.id===id),i=state.instances.find(x=>x.id===id);let title,body;if(action==='publish'){if(!r||r.status!=='approved'||role==='reviewer'||r.author==='林清')return;title='发布 '+r.name+' · '+r.version;body='审核已通过。发布后向 Auriga 用户提供此固定版本，旧版本内容不被覆盖。'}else if(action==='withdraw'){if(!r||r.status!=='published'||role==='reviewer')return;title='下架 '+r.name;body='阻止新的下载和安装；已安装版本不会被自动删除。恶意版本的紧急撤销需要独立处置流程。'}else{if(!i||!permitted('runtime'))return;title=(action==='stop'?'停止':'启动')+i.name;body=action==='stop'?'停止可能中断正在进行的工作，个人数据保留。提交后等待节点执行结果。':'提交启动请求后等待节点回报就绪，登记成功不代表实例已经可用。'}openDialog(title,'<p>'+esc(body)+'</p><p class="sub">仅操作当前浏览器的示例数据。</p>',btn('取消','cancel-confirm',id)+btn('确认模拟'+({publish:'发布',withdraw:'下架',stop:'停止',start:'启动'}[action]),'commit-'+action,id,action==='publish'||action==='start'?'primary':'danger'),true)}
function commit(action,id){if(['publish','withdraw'].includes(action)){const r=state.resources.find(x=>x.id===id);if(!r||role==='reviewer'||(action==='publish'&&(r.status!=='approved'||r.author==='林清'))||(action==='withdraw'&&r.status!=='published'))return;r.status=action==='publish'?'published':'withdrawn';record(action==='publish'?'签发并发布版本':'普通下架版本',r.name+' · '+r.version,'资源');close();render();toast(action==='publish'?'已模拟签发并上架；未调用真实签名服务。':'已模拟下架，已安装内容保留。')}else{const i=state.instances.find(x=>x.id===id);if(!i||!permitted('runtime')||(action==='stop'&&i.status!=='running')||(action==='start'&&i.status!=='stopped'))return;i.status=action==='stop'?'stopping':'starting';i.generation++;i.activity='等待节点执行';record('登记实例'+(action==='stop'?'停止':'启动')+'请求',i.id,'运行环境');render();instanceDetail(id)}}
function roleDialog(){openDialog('切换演示角色','<p>仅预览不同权限下的导航和操作，真实授权由服务端执行。</p><div class="role-options">'+Object.entries(roleNames).map(([k,n])=>'<label class="role-option"><input type="radio" name="demo-role" value="'+k+'" '+(role===k?'checked':'')+'><span><strong>'+n+'</strong><span class="sub">'+({super:'全局配置与平台治理',admin:'日常管理与资源发布',reviewer:'仅查看审核队列与相关审计'}[k])+'</span></span></label>').join('')+'</div>',btn('取消','close')+btn('应用预览','set-role','','primary'),true)}
function invite(){openDialog('创建邀请','<p>在本地生成一条示例邀请记录，不发送链接。</p><label class="form-field">邀请名称<input class="input" id="invite-name" maxlength="50" placeholder="例如：研发成员邀请"></label><label class="form-field">分组<select id="invite-group"><option>研发</option><option>设计</option><option>平台维护</option></select></label><div class="change-line">默认角色：成员　·　名额：5　·　有效期：7 天</div><div id="invite-error" class="error" role="alert"></div>',btn('取消','close')+btn('生成示例邀请','save-invite','','primary'),true)}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,id=el.dataset.id;if(a==='theme'){document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';return}if(a==='go'){close();return navigate(...id.split('/'))}if(a==='tab')return navigate(page,id);if(a==='close')return close();if(a==='refresh'){render();return toast('示例视图已更新，未请求真实服务。')}if(a==='clear'){query='';filter='all';return render()}if(a==='role')return roleDialog();if(a==='set-role'){role=document.querySelector('[name="demo-role"]:checked').value;close();if(!permitted(page))navigate('overview');else if(page==='resources'&&role==='reviewer')navigate('resources','review');else render();return}if(a==='resource')return resourceDetail(id);if(a==='resource-tab')return resourceDetail(...id.split(':'));if(a==='approve'||a==='reject')return decision(id,a==='approve');if(a==='publish-confirm'||a==='withdraw-confirm')return confirmAction(a.split('-')[0],id);if(a==='instance')return instanceDetail(id);if(a==='instance-stop'||a==='instance-start')return confirmAction(a.split('-')[1],id);if(a==='cancel-confirm'){return id.startsWith('ins-')?instanceDetail(id):resourceDetail(id)}if(a.startsWith('commit-'))return commit(a.slice(7),id);if(a==='instance-observed'){const i=state.instances.find(x=>x.id===id);if(!i||!['starting','stopping'].includes(i.status))return;i.status=i.status==='starting'?'running':'stopped';i.observed=i.generation;i.activity=i.status==='running'?'空闲 · 刚启动':'已停止，保留个人数据';record('节点回报'+labels[i.status],i.id,'运行环境');render();return instanceDetail(id)}if(a==='invite')return invite();if(a==='save-invite'){const name=$('invite-name').value.trim();if(!name){$('invite-error').textContent='请填写邀请名称。';return}const expiry=new Date(Date.now()+7*86400000).toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'});state.invites.push({id:'inv-'+Date.now(),name,group:$('invite-group').value,role:'成员',usage:'0 / 5',expiry,status:'有效'});record('创建示例邀请',name,'成员');close();render();return toast('示例邀请已创建，未生成真实授权链接。')}if(['member','device','node','model','audit','policy','backup','lifecycle'].includes(a))details(a,id)});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;render(true)}});
document.addEventListener('change',e=>{if(e.target.id==='status-filter'){filter=e.target.value;render()}});
document.addEventListener('keydown',e=>{if(!$('overlay').children.length)return;if(e.key==='Escape'){e.preventDefault();close()}if(e.key==='Tab'){const nodes=[...$('overlay').querySelectorAll('button:not(:disabled),input,select,textarea')].filter(x=>!x.closest('[hidden]'));if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0]?.focus()}}});
window.addEventListener('hashchange',readRoute);readRoute();
